/** Editable figures on one slide of one deck. */
export function deckFieldsFor(deckMap: string | undefined, slide: number): DeckField[] {
  if (!deckMap) return [];
  return (deckFieldsByDeck[deckMap] ?? []).filter((f) => f.slide === slide);
}
